const { createHash } = require('crypto');
const envelope = $input.first().json;
if (envelope.execution_mode !== 'OFFLINE_EVAL' || envelope.external_effects_allowed !== false) throw new Error('Motor aceita somente OFFLINE_EVAL');
const handoffs = envelope.domain_handoffs ?? [];
const expected = envelope.routing?.selected_domains?.length ?? 0;
if (handoffs.length !== expected) throw new Error('Motor recebeu quantidade incorreta de pareceres');
const allowedDomains = new Set(['conta','performance','financeiro','relacionamento']);
for (const handoff of handoffs) {
  if (handoff.schema_version !== '3.0.0' || handoff.agent_role !== 'GENERAL_MANAGER' || handoff.handoff_level !== 'MANAGER_TO_CONSOLIDATION' || handoff.handoff_target !== 'MOTOR_CONSOLIDACAO_360' || !allowedDomains.has(handoff.domain)) throw new Error('Handoff inválido na fronteira do Motor');
  if (handoff.correlation_id !== envelope.correlation_id || handoff.input_hash !== envelope.input_hash) throw new Error('Handoff não pertence ao snapshot de entrada');
}
const uniqueBy = (items, key) => [...new Map(items.map((item) => [item[key], item])).values()];
const findings = uniqueBy(handoffs.flatMap((handoff) => handoff.findings ?? []), 'finding_id');
const dataGaps = uniqueBy(handoffs.flatMap((handoff) => handoff.data_gaps ?? []).map((gap, index) => ({ ...gap, gap_key: `${gap.field}|${gap.reason_code}|${index}` })), 'gap_key').map(({ gap_key, ...gap }) => gap);
const gates = uniqueBy(handoffs.flatMap((handoff) => handoff.gates ?? []), 'gate_id');
const actions = uniqueBy(handoffs.flatMap((handoff) => handoff.recommended_actions ?? []), 'action_id');
const reviewRequired = envelope.routing.decision_status === 'MANUAL_REVIEW_REQUIRED' || handoffs.some((handoff) => handoff.overall_assessment.decision_status === 'MANUAL_REVIEW_REQUIRED') || dataGaps.some((gap) => gap.requires_manual_review === true) || gates.some((gate) => gate.state === 'MANUAL_REVIEW_REQUIRED');
const state = { schema_version: '1.0.0', tenant_id: envelope.event.tenant_id, subject_ref: envelope.event.subject_ref, event_id: envelope.registration.event_id, correlation_id: envelope.correlation_id, input_hash: envelope.input_hash, generated_at: new Date().toISOString(), overall_status: reviewRequired ? 'MANUAL_REVIEW_REQUIRED' : 'READY', domain_status: handoffs.map((handoff) => ({ domain: handoff.domain, execution_status: handoff.execution_status, evidence_quality: handoff.overall_assessment.evidence_quality, data_completeness: handoff.overall_assessment.data_completeness, decision_status: handoff.overall_assessment.decision_status })), findings, data_gaps: dataGaps, gates, recommended_actions: actions, manual_review: reviewRequired ? (envelope.manual_review ?? { reason_code: 'DOMAIN_REVIEW_REQUIRED', required_decision: 'Revisar os itens indicados pelo Estado 360.', owner_queue: 'REVISAO_DIRETOR_360' }) : null };
const canonicalize = (value) => Array.isArray(value) ? value.map(canonicalize) : value && typeof value === 'object' ? Object.fromEntries(Object.entries(value).sort(([left],[right]) => left.localeCompare(right)).map(([key, entry]) => [key, canonicalize(entry)])) : value;
const stateHash = `sha256:${createHash('sha256').update(JSON.stringify(canonicalize(state)), 'utf8').digest('hex')}`;
return [{ json: { ...envelope, state_candidate: state, state_hash: stateHash } }];

const row = $input.first().json;
const envelope = typeof row.envelope === 'string' ? JSON.parse(row.envelope) : row.envelope;
const snapshot = typeof row.snapshot === 'string' ? JSON.parse(row.snapshot) : row.snapshot;
if (!envelope || !snapshot || !row.state_id) throw new Error('Persistência do Estado 360 não retornou snapshot válido');
delete envelope.state_candidate; delete envelope.state_hash;
return [{ json: { ...envelope, persisted_state: { state_id: row.state_id, state_version: Number(row.state_version), event_id: row.event_id, correlation_id: row.correlation_id, state_hash: row.state_hash, overall_status: row.overall_status, generated_at: row.generated_at, snapshot }, state_registration: { registration_status: row.is_new === true ? 'STATE_PUBLISHED' : 'DUPLICATE_IGNORED', technical_status: row.technical_status, is_new: row.is_new === true, audit_id: Number(row.audit_id) } } }];
